            "exit": {
              "constant_n": 1.52,
              "constant_k": 0.0
            }
          },
          "spectrum": {
            "start_nm": 450.0,
            "stop_nm": 700.0,
            "points": 51
          },
          "illumination": {
            "angles_deg": [0.0],
            "polarizations": ["s"]
          },
          "solver": "smatrix",
          "allow_material_extrapolation": false,
          "requested_outputs": [
            "R",
            "T",
            "A"
