          "physics": {
            "geometry_class": "layered_planar",
            "material_class": "isotropic",
            "excitation_class": "plane_wave",
            "time_domain_required": false
          }
        },
        "targets": [
          {
            "observable": "R",
            "target": 0.0,
            "wavelength_min_nm": 450.0,
            "wavelength_max_nm": 700.0,
            "weight": 1.0,
            "angle_deg": 0.0,
            "polarization": "s",
            "constraint": "at_most",
            "aggregation": "mean",
            "name": "min_mean_reflectance"
          },
          {
            "observable": "R",
            "target": 0.03,
            "wavelength_min_nm": 450.0,
            "wavelength_max_nm": 700.0,
            "weight": 0.5,
            "angle_deg": 0.0,
            "polarization": "s",
            "constraint": "at_most",
            "aggregation": "mean",
            "name": "soft_target_below_0.03"
          }
        ],
        "optimizer": {
          "method": "adam_lbfgs",
          "max_steps": 64,
          "learning_rate": 0.05,
          "starts": 3,
          "seed": 17,
          "early_stop_patience": 15,
          "improvement_tolerance": 1e-7,
          "gradient_clip_norm": 10.0,
          "thickness_window_nm": 100.0,
          "quantization_nm": 1.0
        }
      },
      "objectives": [
        {
          "objective_id": "obj_mean_r",
          "metric": "mean_reflectance",
          "sense": "minimize",
          "weight": 1.0,
          "target": null,
          "region": {
            "wavelength_nm": [
              450.0,
              700.0
            ]
          },
          "admission_role": "score_only"
        },
        {
          "objective_id": "obj_soft_target",
          "metric": "mean_reflectance",
          "sense": "match",
          "weight": 0.5,
          "target": 0.03,
          "region": {
            "wavelength_nm": [
              450.0,
              700.0
            ]
          },
          "admission_role": "score_only"
        }
      ],
      "tags": [
        "ar_coating",
        "two_layer",
        "tio2_sio2"
      ]
    }
  ],
  "uncertainty": {
    "thickness_sigma_nm": 1.0,
    "thickness_error_model": "absolute_normal",
    "thickness_relative_fraction": 0.0,
    "thickness_samples": 16,
    "angle_perturbation_deg": 0.0,
    "material_dataset_policy": "resolved_only",
    "maximum_material_scenarios": 8,
    "random_seed": 42
  }
}

